const publishLifecycleSoftwareApplicationVersion = `-- name: PublishLifecycleSoftwareApplicationVersion :one
WITH target AS (
    SELECT
        software_application_id
    FROM
        software_application_versions
    WHERE
        id = $2
        AND STATUS = 'SUBMITTED' FOR
    UPDATE
),
archived AS (
    UPDATE
        software_application_versions
    SET
        STATUS = 'ARCHIVED',
        archived_by = $1,
        archived_at = NOW()
    WHERE
        software_application_id = (
            SELECT
                software_application_id
            FROM
                target
        )
        AND STATUS = 'PUBLISHED'
)
UPDATE
    software_application_versions
SET
    STATUS = 'PUBLISHED',
    published_by = $1,
    published_at = NOW(),
    rejected_by = NULL,
    rejected_at = NULL,
    rejection_note = NULL
WHERE
    software_application_versions.id = $2
    AND software_application_versions.status = 'SUBMITTED'
RETURNING
    id, software_application_id, status, revision, name, description, main_entity_of_page, license, version, keywords, download_url, requirements, operating_system, created_by, created_at, updated_at, submitted_by, submitted_at, published_by, published_at, archived_by, archived_at, rejected_by, rejected_at, rejection_note
`

